import{_ as a}from"./chunks/popup-network.DtVnjL4E.js";import{_ as r}from"./chunks/options-network.nE0FPv2h.js";import{_ as e,o,c as i,a2 as l}from"./chunks/framework.CfwCq2QB.js";const g=JSON.parse('{"title":"代理与自动分流","description":"","frontmatter":{},"headers":[],"relativePath":"features/proxy.md","filePath":"features/proxy.md"}'),d={name:"features/proxy.md"};function s(n,t,h,c,p,u){return o(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="代理与自动分流" tabindex="-1">代理与自动分流 <a class="header-anchor" href="#代理与自动分流" aria-label="Permalink to &quot;代理与自动分流&quot;">​</a></h1><p>一句话：直连 / 系统代理 / 自动模式 / 代理模式一键切换，也可以新增自定义代理模式；每种模式分别保存代理服务器和绕过列表。</p><h2 id="四种网络模式" tabindex="-1">四种网络模式 <a class="header-anchor" href="#四种网络模式" aria-label="Permalink to &quot;四种网络模式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模式</th><th>行为</th></tr></thead><tbody><tr><td>直连</td><td>不使用代理</td></tr><tr><td>系统代理</td><td>跟随系统设置</td></tr><tr><td>自动模式</td><td>按规则自动分流：命中规则走代理，其余按你选的默认去向</td></tr><tr><td>代理模式</td><td>全部流量走代理</td></tr></tbody></table><p>入口：弹窗「网络」页（<code>Alt+3</code>）一键切换；设置页「网络」做完整配置。</p><img src="'+a+'" alt="弹窗网络页"><h2 id="单站点快捷切换" tabindex="-1">单站点快捷切换 <a class="header-anchor" href="#单站点快捷切换" aria-label="Permalink to &quot;单站点快捷切换&quot;">​</a></h2><p>弹窗「网络」页底部有当前网站的快捷开关：</p><ul><li><strong>当前站点直连</strong>：临时让某个网站绕过代理（比如代理下访问不了国内站）</li><li><strong>当前站点走代理</strong>：只让当前网站走代理（自动模式的「自定义代理域名」同理，优先于规则列表）</li></ul><h2 id="自动模式详解" tabindex="-1">自动模式详解 <a class="header-anchor" href="#自动模式详解" aria-label="Permalink to &quot;自动模式详解&quot;">​</a></h2><p>自动模式 = 规则列表 + 自定义域名 + 默认去向：</p><ul><li><strong>规则列表</strong>：AutoProxy / GFWList 格式，启用后命中规则的站点走代理，每 6 小时自动更新，也可手动「更新 / 下载」</li><li><strong>自定义代理域名</strong>：规则没收录但需要走代理的站点，每行一个域名（自动包含子域名）</li><li><strong>未命中规则时</strong>：默认「直连」（只有命中才走代理）；如果你的代理软件自带分流，可以改成「走代理」——除绕过列表、局域网和 <code>.cn</code> 域名外全部走代理</li></ul><p>没有任何规则、也没有自定义域名时，自动模式等于直连。</p><h2 id="自定义代理模式" tabindex="-1">自定义代理模式 <a class="header-anchor" href="#自定义代理模式" aria-label="Permalink to &quot;自定义代理模式&quot;">​</a></h2><p>除了内置模式，可以「新增自定义模式」，给不同的代理服务器起名（如「工作」「家庭」），一键互相切换。每个模式独立保存代理服务器（协议 / Host / 端口）和绕过列表。</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ul><li><strong>代理服务器与绕过列表</strong>修改后要点「保存并应用」才生效；规则列表、代理域名和真实 IP 防护即时生效</li><li>代理配置保存栏吸底显示，有未保存修改时会高亮提醒，离开前会确认</li><li>开启「切换代理后刷新页面」，在弹窗切换模式后当前网页自动刷新，避免新旧连接混用</li><li>DevGo 接管代理后，浏览器扩展卡片会显示「已由 DevGo 控制」；若显示「被其他扩展控制」，需要先停用那个扩展</li><li><strong>Firefox 暂不支持</strong>代理切换（Chromium 专有 API 限制），见 <a href="/dev-go-docs/faq/#firefox-里代理切换不可用">FAQ</a></li></ul><img src="'+r+'" alt="网络设置">',18)])])}const b=e(d,[["render",s]]);export{g as __pageData,b as default};
